def replay(): # Resolve an observed historical hash mismatch through a new real solver execution rather than rewriting the old receipt.
    old=DYN/'native/girder_reference/frequency';new=DYN/'native/girder_reference/frequency_replay_v2';new.mkdir(parents=True,exist_ok=True);original=json.loads((old/'receipt.json').read_text());observed=sha(old/'model.dat');(new/'model.inp').write_bytes((old/'model.inp').read_bytes());start=time.time() # Preserve old bytes and receipt while freezing the identical replay input separately.
    with (new/'solver.log').open('w') as stream: process=subprocess.run([str(CCX),'-i','model'],cwd=new,stdout=stream,stderr=subprocess.STDOUT,timeout=60) # Execute a complete fresh native frequency analysis.
    def frequencies(path): # Extract only actual printed cycles-per-second modal values.
        return [float(line.split()[3]) for line in path.read_text().split('P A R T I C I P A T I O N')[0].splitlines() if re.match(r'^\s*\d+\s+[-+0-9.E]+\s+[-+0-9.E]+\s+[-+0-9.E]+\s+[-+0-9.E]+\s*$',line)] # Retain native printed precision without interpreting modal participation signs as different frequencies.
    a=frequencies(old/'model.dat');b=frequencies(new/'model.dat');assert len(a)==len(b)==24;difference=max(abs(x-y)/max(abs(y),1e-20) for x,y in zip(a,b));log=(new/'solver.log').read_text();receipt={'case':'girder_reference','mode':'frequency_replay_v2','returncode':process.returncode,'finished':'Job finished' in log and '*ERROR' not in log,'seconds':time.time()-start,'input_sha256':sha(new/'model.inp'),'dat_sha256':sha(new/'model.dat'),'solver_log_sha256':sha(new/'solver.log'),'supersedes_receipt':str((old/'receipt.json').relative_to(REPO)),'original_receipt_expected_dat_sha256':original['dat_sha256'],'observed_old_dat_sha256':observed,'historical_mismatch_preserved':observed!=original['dat_sha256'],'old_input_hash_matches':sha(old/'model.inp')==original['input_sha256'],'old_vs_replay_printed_frequency_max_relative':difference,'reason':'Historical DAT digest mismatch found by independent audit; cause not established. Old input/DAT/receipt remain unchanged. This independently executed same-input run is the final authoritative native-frequency receipt.'};assert process.returncode==0 and receipt['finished'] and difference<1e-6 and receipt['old_input_hash_matches'];write_json(new/'receipt.json',receipt);write_json(DYN/'native_frequency_supersession.json',receipt);print(json.dumps(receipt),flush=True) # Publish the new authoritative record while retaining the original discrepancy honestly.
